1. package hcloud
2. 
3. import (
4. 	"context"
5. 	"errors"
6. 	"fmt"
7. 	"net"
8. 	"time"
9. 
10. 	"golang.org/x/time/rate"
11. 	"k8s.io/apimachinery/pkg/types"
12. 	cloudprovider "k8s.io/cloud-provider"
13. 	"k8s.io/klog/v2"
14. 
15. 	"github.com/hetznercloud/hcloud-cloud-controller-manager/internal/hcops"
16. 	"github.com/hetznercloud/hcloud-cloud-controller-manager/internal/metrics"
17. 	"github.com/hetznercloud/hcloud-go/v2/hcloud"
18. )
19. 
20. var (
21. 	serversCacheMissRefreshRate = rate.Every(30 * time.Second)
22. )
23. 
24. type routes struct {
25. 	client      *hcloud.Client
26. 	network     *hcloud.Network
27. 	serverCache *hcops.AllServersCache
28. }
29. 
30. func newRoutes(client *hcloud.Client, networkID int64) (*routes, error) {
31. 	const op = "hcloud/newRoutes"
32. 	metrics.OperationCalled.WithLabelValues(op).Inc()
33. 
34. 	networkObj, _, err := client.Network.GetByID(context.Background(), networkID)
35. 	if err != nil {
36. 		return nil, fmt.Errorf("%s: %w", op, err)
37. 	}
38. 	if networkObj == nil {
39. 		return nil, fmt.Errorf("network not found: %d", networkID)
40. 	}
41. 
42. 	return &routes{
43. 		client:  client,
44. 		network: networkObj,
45. 		serverCache: &hcops.AllServersCache{
46. 			// client.Server.All will load ALL the servers in the project, even those
47. 			// that are not part of the Kubernetes cluster.
48. 			LoadFunc:                client.Server.All,
49. 			Network:                 networkObj,
50. 			CacheMissRefreshLimiter: rate.NewLimiter(serversCacheMissRefreshRate, 1),
51. 		},
52. 	}, nil
53. }
54. 
55. func (r *routes) reloadNetwork(ctx context.Context) error {
56. 	const op = "hcloud/reloadNetwork"
57. 	metrics.OperationCalled.WithLabelValues(op).Inc()
58. 
59. 	networkObj, _, err := r.client.Network.GetByID(ctx, r.network.ID)
60. 	if err != nil {
61. 		return fmt.Errorf("%s: %w", op, err)
62. 	}
63. 	if networkObj == nil {
64. 		return fmt.Errorf("network not found: %s", r.network.Name)
65. 	}
66. 	r.network = networkObj
67. 	return nil
68. }
69. 
70. // ListRoutes lists all managed routes that belong to the specified clusterName.
71. func (r *routes) ListRoutes(ctx context.Context, _ string) ([]*cloudprovider.Route, error) {
72. 	const op = "hcloud/ListRoutes"
73. 	metrics.OperationCalled.WithLabelValues(op).Inc()
74. 
75. 	if err := r.reloadNetwork(ctx); err != nil {
76. 		return nil, fmt.Errorf("%s: %w", op, err)
77. 	}
78. 
79. 	routes := make([]*cloudprovider.Route, 0, len(r.network.Routes))
80. 	for _, route := range r.network.Routes {
81. 		ro, err := r.hcloudRouteToRoute(route)
82. 		if err != nil {
83. 			return routes, fmt.Errorf("%s: %w", op, err)
84. 		}
85. 		routes = append(routes, ro)
86. 	}
87. 	return routes, nil
88. }
89. 
90. // CreateRoute creates the described managed route
91. // route.Name will be ignored, although the cloud-provider may use nameHint
92. // to create a more user-meaningful name.
93. func (r *routes) CreateRoute(ctx context.Context, clusterName string, nameHint string, route *cloudprovider.Route) error {
94. 	const op = "hcloud/CreateRoute"
95. 	metrics.OperationCalled.WithLabelValues(op).Inc()
96. 
97. 	srv, err := r.serverCache.ByName(string(route.TargetNode))
98. 	if err != nil {
99. 		return fmt.Errorf("%s: %v", op, err)
100. 	}
101. 
102. 	privNet, ok := findServerPrivateNetByID(srv, r.network.ID)
103. 	if !ok {
104. 		r.serverCache.InvalidateCache()
105. 		srv, err = r.serverCache.ByName(string(route.TargetNode))
106. 		if err != nil {
107. 			return fmt.Errorf("%s: %v", op, err)
108. 		}
109. 
110. 		privNet, ok = findServerPrivateNetByID(srv, r.network.ID)
111. 		if !ok {
112. 			return fmt.Errorf("%s: server %v: network with id %d not attached to this server", op, route.TargetNode, r.network.ID)
113. 		}
114. 	}
115. 	ip := privNet.IP
116. 
117. 	_, cidr, err := net.ParseCIDR(route.DestinationCIDR)
118. 	if err != nil {
119. 		return fmt.Errorf("%s: %w", op, err)
120. 	}
121. 
122. 	doesRouteAlreadyExist, err := r.checkIfRouteAlreadyExists(ctx, route)
123. 	if err != nil {
124. 		return fmt.Errorf("%s: %w", op, err)
125. 	}
126. 
127. 	if !doesRouteAlreadyExist {
128. 		opts := hcloud.NetworkAddRouteOpts{
129. 			Route: hcloud.NetworkRoute{
130. 				Destination: cidr,
131. 				Gateway:     ip,
132. 			},
133. 		}
134. 		action, _, err := r.client.Network.AddRoute(ctx, r.network, opts)
135. 		if err != nil {
136. 			if hcloud.IsError(err, hcloud.ErrorCodeLocked) || hcloud.IsError(err, hcloud.ErrorCodeConflict) {
137. 				retryDelay := time.Second * 5
138. 				klog.InfoS("retry due to conflict or lock",
139. 					"op", op, "delay", fmt.Sprintf("%v", retryDelay), "err", fmt.Sprintf("%v", err))
140. 				time.Sleep(retryDelay)
141. 
142. 				return r.CreateRoute(ctx, clusterName, nameHint, route)
143. 			}
144. 			return fmt.Errorf("%s: %w", op, err)
145. 		}
146. 
147. 		if err := hcops.WatchAction(ctx, &r.client.Action, action); err != nil {
148. 			return fmt.Errorf("%s: %w", op, err)
149. 		}
150. 	}
151. 	return nil
152. }
153. 
154. // DeleteRoute deletes the specified managed route
155. // Route should be as returned by ListRoutes.
156. func (r *routes) DeleteRoute(ctx context.Context, _ string, route *cloudprovider.Route) error {
157. 	const op = "hcloud/DeleteRoute"
158. 	metrics.OperationCalled.WithLabelValues(op).Inc()
159. 
160. 	// Get target IP from current list of routes, routes can be uniquely identified by their destination cidr.
161. 	var ip net.IP
162. 	for _, cloudRoute := range r.network.Routes {
163. 		if cloudRoute.Destination.String() == route.DestinationCIDR {
164. 			ip = cloudRoute.Gateway
165. 			break
166. 		}
167. 	}
168. 	if ip.IsUnspecified() {
169. 		return fmt.Errorf("%s: route %s not found in cloud network routes", op, route.Name)
170. 	}
171. 
172. 	_, cidr, err := net.ParseCIDR(route.DestinationCIDR)
173. 	if err != nil {
174. 		return fmt.Errorf("%s: %w", op, err)
175. 	}
176. 
177. 	err = r.deleteRouteFromHcloud(ctx, cidr, ip)
178. 	if err != nil {
179. 		return fmt.Errorf("%s: %w", op, err)
180. 	}
181. 	return nil
182. }
183. 
184. func (r *routes) deleteRouteFromHcloud(ctx context.Context, cidr *net.IPNet, ip net.IP) error {
185. 	const op = "hcloud/deleteRouteFromHcloud"
186. 	metrics.OperationCalled.WithLabelValues(op).Inc()
187. 
188. 	opts := hcloud.NetworkDeleteRouteOpts{
189. 		Route: hcloud.NetworkRoute{
190. 			Destination: cidr,
191. 			Gateway:     ip,
192. 		},
193. 	}
194. 
195. 	action, _, err := r.client.Network.DeleteRoute(ctx, r.network, opts)
196. 	if err != nil {
197. 		if hcloud.IsError(err, hcloud.ErrorCodeLocked) || hcloud.IsError(err, hcloud.ErrorCodeConflict) {
198. 			retryDelay := time.Second * 5
199. 			klog.InfoS("retry due to conflict or lock",
200. 				"op", op, "delay", fmt.Sprintf("%v", retryDelay), "err", fmt.Sprintf("%v", err))
201. 			time.Sleep(retryDelay)
202. 
203. 			return r.deleteRouteFromHcloud(ctx, cidr, ip)
204. 		}
205. 		return fmt.Errorf("%s: %w", op, err)
206. 	}
207. 	if err := hcops.WatchAction(ctx, &r.client.Action, action); err != nil {
208. 		return fmt.Errorf("%s: %w", op, err)
209. 	}
210. 	return nil
211. }
212. 
213. func (r *routes) hcloudRouteToRoute(route hcloud.NetworkRoute) (*cloudprovider.Route, error) {
214. 	const op = "hcloud/hcloudRouteToRoute"
215. 	metrics.OperationCalled.WithLabelValues(op).Inc()
216. 
217. 	cpRoute := &cloudprovider.Route{
218. 		DestinationCIDR: route.Destination.String(),
219. 		Name:            fmt.Sprintf("%s-%s", route.Gateway.String(), route.Destination.String()),
220. 	}
221. 
222. 	srv, err := r.serverCache.ByPrivateIP(route.Gateway)
223. 	if err != nil {
224. 		if errors.Is(err, hcops.ErrNotFound) {
225. 			// Route belongs to non-existing target
226. 			cpRoute.Blackhole = true
227. 			return cpRoute, nil
228. 		}
229. 
230. 		return nil, fmt.Errorf("%s: %w", op, err)
231. 	}
232. 
233. 	cpRoute.TargetNode = types.NodeName(srv.Name)
234. 	return cpRoute, nil
235. }
236. 
237. func (r *routes) checkIfRouteAlreadyExists(ctx context.Context, route *cloudprovider.Route) (bool, error) {
238. 	const op = "hcloud/checkIfRouteAlreadyExists"
239. 	metrics.OperationCalled.WithLabelValues(op).Inc()
240. 
241. 	if err := r.reloadNetwork(ctx); err != nil {
242. 		return false, fmt.Errorf("%s: %w", op, err)
243. 	}
244. 
245. 	for _, _route := range r.network.Routes {
246. 		if _route.Destination.String() == route.DestinationCIDR {
247. 			srv, err := r.serverCache.ByName(string(route.TargetNode))
248. 			if err != nil {
249. 				return false, fmt.Errorf("%s: %v", op, err)
250. 			}
251. 			privNet, ok := findServerPrivateNetByID(srv, r.network.ID)
252. 			if !ok {
253. 				return false, fmt.Errorf("%s: server %v: no network with id: %d", op, route.TargetNode, r.network.ID)
254. 			}
255. 			ip := privNet.IP
256. 
257. 			if !_route.Gateway.Equal(ip) {
258. 				action, _, err := r.client.Network.DeleteRoute(context.Background(), r.network, hcloud.NetworkDeleteRouteOpts{
259. 					Route: _route,
260. 				})
261. 				if err != nil {
262. 					return false, fmt.Errorf("%s: %w", op, err)
263. 				}
264. 
265. 				if err := hcops.WatchAction(ctx, &r.client.Action, action); err != nil {
266. 					return false, fmt.Errorf("%s: %w", op, err)
267. 				}
268. 			}
269. 
270. 			return true, nil
271. 		}
272. 	}
273. 	return false, nil
274. }
275. 
276. func findServerPrivateNetByID(srv *hcloud.Server, id int64) (hcloud.ServerPrivateNet, bool) {
277. 	for _, n := range srv.PrivateNet {
278. 		if n.Network.ID == id {
279. 			return n, true
280. 		}
281. 	}
282. 	return hcloud.ServerPrivateNet{}, false
283. }
284.

