 import (
 	"context"
+	"fmt"
+	"time"

 	"github.com/hetznercloud/hcloud-go/v2/hcloud"
 )

 type HCloudActionClient interface {
 	WatchProgress(ctx context.Context, a *hcloud.Action) (<-chan int, <-chan error)
 }

+type hcloudActionGetter interface {
+	GetByID(ctx context.Context, id int64) (*hcloud.Action, *hcloud.Response, error)
+}
+
 func WatchAction(ctx context.Context, ac HCloudActionClient, a *hcloud.Action) error {
+	if ag, ok := ac.(hcloudActionGetter); ok {
+		return watchActionByID(ctx, ag, a)
+	}
+
 	_, errCh := ac.WatchProgress(ctx, a)
 	err := <-errCh
 	return err
 }
+
+func watchActionByID(ctx context.Context, ac hcloudActionGetter, a *hcloud.Action) error {
+	if a == nil {
+		return nil
+	}
+
+	switch a.Status {
+	case hcloud.ActionStatusSuccess:
+		return nil
+	case hcloud.ActionStatusError:
+		return a.Error()
+	}
+
+	ticker := time.NewTicker(500 * time.Millisecond)
+	defer ticker.Stop()
+
+	for {
+		select {
+		case <-ctx.Done():
+			return ctx.Err()
+		case <-ticker.C:
+		}
+
+		update, _, err := ac.GetByID(ctx, a.ID)
+		if err != nil {
+			return err
+		}
+		if update == nil {
+			return fmt.Errorf("failed to wait for action %d: action not returned from API", a.ID)
+		}
+
+		switch update.Status {
+		case hcloud.ActionStatusRunning:
+			continue
+		case hcloud.ActionStatusSuccess:
+			return nil
+		case hcloud.ActionStatusError:
+			return update.Error()
+		}
+	}
+}
*** End Patch

